def solve_langford(n):
    seq = [0] * (2 * n)
    def backtrack(num):
        if num == 0:
            return True
        for i in range(2 * n - num - 1):
            if seq[i] == 0 and seq[i + num + 1] == 0:
                seq[i] = num
                seq[i + num + 1] = num
                if backtrack(num - 1):
                    return True
                seq[i] = 0
                seq[i + num + 1] = 0
        return False
    if backtrack(n):
        return seq
    return None

print(solve_langford(11))
